DROP TABLE IF EXISTS `activities`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `activities` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `media_id` bigint unsigned DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `icon_class` varchar(100) DEFAULT NULL,
  `short_description` text NOT NULL,
  `full_description` longtext,
  `duration` varchar(100) DEFAULT NULL,
  `difficulty` enum('easy','moderate','challenging','extreme') DEFAULT 'moderate',
  `price_from` decimal(10,2) DEFAULT NULL,
  `currency` char(3) DEFAULT 'USD',
  `best_season` varchar(255) DEFAULT NULL,
  `group_size_min` int DEFAULT '1',
  `group_size_max` int DEFAULT '20',
  `highlights` json DEFAULT NULL,
  `inclusions` json DEFAULT NULL,
  `exclusions` json DEFAULT NULL,
  `requirements` text,
  `location` varchar(255) DEFAULT NULL,
  `is_featured` tinyint(1) DEFAULT '0',
  `is_active` tinyint(1) DEFAULT '1',
  `display_order` int DEFAULT '0',
  `meta_title` varchar(255) DEFAULT NULL,
  `meta_description` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `is_active` (`is_active`,`is_featured`),
  KEY `display_order` (`display_order`),
  KEY `media_id` (`media_id`),
  KEY `idx_activities_featured` (`is_featured`,`is_active`),
  KEY `idx_activities_difficulty` (`difficulty`),
  KEY `idx_activities_display` (`display_order`),
  CONSTRAINT `activities_ibfk_1` FOREIGN KEY (`media_id`) REFERENCES `media_library` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
