INSERT INTO `routes` VALUES (1,3,NULL,NULL,'Everest Base Camp Trek','everest-base-camp-trek','challenging',14,5364,'March to May, October to November','mixed','trek',7,0,1299.00,'USD',NULL,'Trek to the base of the world\'s highest mountain on this iconic 14-day adventure.','Experience the thrill of standing at Everest Base Camp (5,364m) on this classic trek through the Khumbu region. Walk in the footsteps of legendary mountaineers, visit ancient Buddhist monasteries, and immerse yourself in Sherpa culture. This challenging trek offers breathtaking views of Everest, Lhotse, Nuptse, and Ama Dablam.','[\"Stand at Everest Base Camp (5,364m) — the foot of the world\'s highest mountain\", \"Sunrise from Kala Patthar (5,545m) with the closest Everest panorama on earth\", \"Explore the Sherpa capital of Namche Bazaar and its bustling Saturday market\", \"Visit the sacred Tengboche Monastery with Ama Dablam as backdrop\", \"Trek through Sagarmatha National Park — a UNESCO World Heritage Site\", \"Sweeping views of Lhotse, Nuptse, Pumori, and the Khumbu Glacier\"]','[\"Airport and hotel transfers in Kathmandu\", \"Lukla round-trip flight (Kathmandu–Lukla–Kathmandu)\", \"Tea house accommodation throughout the trek\", \"All meals on trek (breakfast, lunch, dinner)\", \"Experienced English-speaking trekking guide\", \"One porter per two trekkers (max 15 kg luggage)\", \"Sagarmatha National Park entry permit\", \"TIMS card (Trekkers Information Management System)\", \"First aid kit and pulse oximeter\", \"Yeti Routes duffel bag and trekking map\"]','[\"International flights to/from Nepal\", \"Nepal entry visa fee (USD 30 / USD 50)\", \"Travel and rescue insurance (mandatory)\", \"Meals and accommodation in Kathmandu\", \"Personal trekking gear (boots, sleeping bag, down jacket)\", \"Personal expenses (hot shower, charging, laundry, bottled water)\", \"Alcoholic beverages and soft drinks\", \"Tips for guides and porters (customary)\", \"Helicopter rescue costs if required\"]',NULL,NULL,1,NULL,NULL,NULL,'Everest Base Camp Trek | 14 Days | From $1,299 | Yeti Routes','Classic 14-day Everest Base Camp Trek (5,364m). Kala Patthar sunrise, Namche Bazaar & Tengboche. Expert guides, small groups. Book with Yeti Routes.',1),(2,10,NULL,NULL,'Annapurna Circuit Trek','annapurna-circuit-trek','moderate',16,5416,'March to May, October to November','mixed','expedition',6,0,990.00,'USD',NULL,'A classic teahouse trek circling the Annapurna massif, crossing the dramatic Thorong La Pass.','The Annapurna Circuit is often voted the best long-distance trek in the world. It takes you from subtropical jungles to the high-altitude arid landscapes of Manang and Mustang. The highlight is crossing the Thorong La Pass at 5,416m.','[\"Cross the iconic Thorong La Pass (5,416m) — one of the world\'s highest trekking passes\", \"Visit the sacred Hindu and Buddhist temples of Muktinath (3,760m)\", \"Explore Tilicho Lake (4,919m) — one of the world\'s highest lakes (optional extension)\", \"Experience the dramatic kali Gandaki Gorge, the world\'s deepest gorge\", \"Poon Hill sunrise (3,210m) with panoramic views of Dhaulagiri and Annapurna ranges\", \"Complete circuit of the entire Annapurna massif through diverse landscapes\"]','[\"Airport and hotel transfers in Kathmandu\", \"Kathmandu–Besisahar and Pokhara–Kathmandu transport\", \"Tea house accommodation throughout the trek\", \"All meals on trek (breakfast, lunch, dinner)\", \"Experienced English-speaking trekking guide\", \"One porter per two trekkers (max 15 kg luggage)\", \"Annapurna Conservation Area permit (ACAP)\", \"TIMS card\", \"First aid kit and pulse oximeter\", \"Sleeping bag (rental available for high sections)\", \"Yeti Routes duffel bag and trekking map\"]','[\"International flights to/from Nepal\", \"Nepal entry visa fee\", \"Travel and rescue insurance (mandatory)\", \"Meals and accommodation in Kathmandu and Pokhara\", \"Personal trekking gear\", \"Personal expenses\", \"Alcoholic beverages and soft drinks\", \"Tips for guides and porters\", \"Helicopter rescue costs if required\"]',NULL,NULL,1,NULL,NULL,NULL,'Annapurna Circuit Trek | 16 Days | Thorong La | Yeti Routes','16-day Annapurna Circuit Trek. Thorong La Pass (5,416m), Muktinath, Poon Hill & Kali Gandaki Gorge. The classic Nepal circuit. Yeti Routes.',1),(3,11,NULL,NULL,'Langtang Valley Trek','langtang-valley-trek','moderate',10,4984,'March to May, October to November','forest','trek',5,0,650.00,'USD',NULL,'The valley of glaciers. A beautiful, culturally rich trek easily accessible from Kathmandu.','Langtang Valley is known as the valley of glaciers. It offers pine forests, swift mountain streams, rugged rock and snow-capped peaks, grassy downs and meadows strewn with daisies and wild primulas.','[\"Reach the tranquil Kyanjin Gompa monastery at 3,870m in the heart of Langtang Valley\", \"Panoramic views of Langtang Lirung (7,227m) — the valley\'s guardian peak\", \"Explore traditional Tamang villages with rich Buddhist heritage and yak cheese farms\", \"Trek through Langtang National Park\'s dense rhododendron and bamboo forests\", \"Optional hike to Kyanjin Ri (4,773m) for a stunning 360° Himalayan panorama\", \"One of Nepal\'s closest trekking destinations to Kathmandu — just 7 hours by road\"]','[\"Airport and hotel transfers in Kathmandu\", \"Kathmandu–Syabrubesi–Kathmandu transport\", \"Tea house accommodation throughout the trek\", \"All meals on trek (breakfast, lunch, dinner)\", \"Experienced English-speaking trekking guide\", \"One porter per two trekkers (max 15 kg luggage)\", \"Langtang National Park entry permit\", \"TIMS card\", \"First aid kit\", \"Yeti Routes duffel bag and trekking map\"]','[\"International flights to/from Nepal\", \"Nepal entry visa fee\", \"Travel and rescue insurance (mandatory)\", \"Meals and accommodation in Kathmandu\", \"Personal trekking gear\", \"Personal expenses (hot shower, charging, bottled water)\", \"Alcoholic beverages and soft drinks\", \"Tips for guides and porters\", \"Helicopter rescue costs if required\"]',NULL,NULL,0,NULL,NULL,NULL,'Langtang Valley Trek | 10 Days | From $650 | Yeti Routes','10-day Langtang Valley Trek to Kyanjin Gompa (3,870m). Closest major trek to Kathmandu. Tamang culture, yak cheese & Himalayan views. Yeti Routes.',1),(4,12,NULL,NULL,'Manaslu Circuit Trek','manaslu-circuit-trek','extreme',14,5106,'March to May, October to November','snow','trek',8,0,1150.00,'USD',NULL,'A restricted area trek around the world\'s 8th highest mountain. Less crowded and wild.','Experience the untouched beauty of the Manaslu region. This trek is a great alternative to the Annapurna Circuit, offering similar views but with far fewer crowds and more authentic culture.','[\"Cross the awe-inspiring Larkya La Pass (5,160m) with views of Manaslu\'s north face\", \"Complete circuit of Mt. Manaslu (8,163m) — the 8th highest mountain in the world\", \"Trek through the remote Nubri and Tsum valleys with preserved Tibetan Buddhist culture\", \"Explore ancient Tibetan gompas and mani walls along the trail\", \"Restricted area permit — a less-visited alternative to the Annapurna Circuit\", \"Diverse landscapes from subtropical river valleys to high-altitude glacial terrain\"]','[\"Airport and hotel transfers in Kathmandu\", \"Kathmandu–Machha Khola–Kathmandu transport\", \"Tea house and guesthouse accommodation\", \"All meals on trek (breakfast, lunch, dinner)\", \"Experienced English-speaking trekking guide\", \"One porter per two trekkers (max 15 kg luggage)\", \"Manaslu Restricted Area Permit\", \"Manaslu Conservation Area entry permit\", \"TIMS card\", \"First aid kit and pulse oximeter\", \"Sleeping bag and down jacket (rental available)\", \"Yeti Routes duffel bag and trekking map\"]','[\"International flights to/from Nepal\", \"Nepal entry visa fee\", \"Travel and rescue insurance (mandatory)\", \"Meals and accommodation in Kathmandu\", \"Personal trekking gear\", \"Personal expenses\", \"Alcoholic beverages and soft drinks\", \"Tips for guides and porters\", \"Helicopter rescue costs if required\"]',NULL,NULL,1,NULL,NULL,NULL,'Manaslu Circuit Trek | 14 Days | Restricted Area | Yeti Routes','14-day Manaslu Circuit Trek. Larkya La Pass (5,160m), circuit of 8,163m Manaslu, Tibetan culture. Restricted permit, small groups. Yeti Routes Nepal.',1),(20,3,NULL,NULL,'Everest Base Camp Trek','everest-base-camp','challenging',14,5545,'March to May, October to November','mixed','trek',7,0,1299.00,'USD',NULL,'The classic trek to the foot of the world\'s highest peak.','Itinerary: Lukla > Phakding > Namche > Tengboche > Dingboche > Lobuche > EBC > Kala Patthar > Return.','[\"Stand at Everest Base Camp (5,364m) — the foot of the world\'s highest mountain\", \"Sunrise from Kala Patthar (5,545m) with the closest Everest panorama on earth\", \"Explore the Sherpa capital of Namche Bazaar and its bustling Saturday market\", \"Visit the sacred Tengboche Monastery with Ama Dablam as backdrop\", \"Trek through Sagarmatha National Park — a UNESCO World Heritage Site\", \"Sweeping views of Lhotse, Nuptse, Pumori, and the Khumbu Glacier\"]','[\"Airport and hotel transfers in Kathmandu\", \"Lukla round-trip flight (Kathmandu–Lukla–Kathmandu)\", \"Tea house accommodation throughout the trek\", \"All meals on trek (breakfast, lunch, dinner)\", \"Experienced English-speaking trekking guide\", \"One porter per two trekkers (max 15 kg luggage)\", \"Sagarmatha National Park entry permit\", \"TIMS card (Trekkers Information Management System)\", \"First aid kit and pulse oximeter\", \"Yeti Routes duffel bag and trekking map\"]','[\"International flights to/from Nepal\", \"Nepal entry visa fee (USD 30 / USD 50)\", \"Travel and rescue insurance (mandatory)\", \"Meals and accommodation in Kathmandu\", \"Personal trekking gear (boots, sleeping bag, down jacket)\", \"Personal expenses (hot shower, charging, laundry, bottled water)\", \"Alcoholic beverages and soft drinks\", \"Tips for guides and porters (customary)\", \"Helicopter rescue costs if required\"]',NULL,NULL,0,NULL,NULL,NULL,'Everest Base Camp Trek | 14 Days | From $1,299 | Yeti Routes','Classic 14-day Everest Base Camp Trek (5,364m). Kala Patthar sunrise, Namche Bazaar & Tengboche. Expert guides, small groups. Book with Yeti Routes.',0),(21,3,NULL,NULL,'Everest Three Passes Trek','three-passes-trek','extreme',20,5535,'March to May, October to November','snow','expedition',9,0,1650.00,'USD',NULL,'The ultimate high-altitude circuit crossing Renjo La, Cho La, and Kongma La.','Itinerary: Renjo La > Gokyo > Cho La > EBC > Kongma La > Return. A challenging adventure for experienced trekkers.','[\"Cross three legendary high passes: Kongma La (5,535m), Cho La (5,420m), and Renjo La (5,360m)\", \"Stand at Everest Base Camp (5,364m) and summit Kala Patthar (5,545m)\", \"Explore the sacred Gokyo Lakes and summit Gokyo Ri (5,357m) for 8,000m peak panoramas\", \"Complete the ultimate Everest region circuit — the full Khumbu experience\", \"Walk across Ngozumpa Glacier, Nepal\'s largest glacier\", \"Physically demanding adventure for seasoned trekkers seeking the ultimate Himalayan challenge\"]','[\"Airport and hotel transfers in Kathmandu\", \"Lukla round-trip flight (Kathmandu–Lukla–Kathmandu)\", \"Tea house accommodation throughout the trek\", \"All meals on trek (breakfast, lunch, dinner)\", \"Experienced English-speaking trekking guide\", \"One porter per two trekkers (max 15 kg luggage)\", \"Sagarmatha National Park entry permit\", \"TIMS card\", \"First aid kit and pulse oximeter\", \"Sleeping bag and down jacket (rental available)\", \"Yeti Routes duffel bag and detailed trekking map\"]','[\"International flights to/from Nepal\", \"Nepal entry visa fee\", \"Travel and rescue insurance (mandatory)\", \"Meals and accommodation in Kathmandu\", \"Personal trekking gear (boots, waterproof layers)\", \"Personal expenses (hot shower, charging, bottled water)\", \"Alcoholic beverages and soft drinks\", \"Tips for guides and porters\", \"Helicopter rescue costs if required\"]',NULL,NULL,1,NULL,NULL,NULL,'Everest Three Passes Trek | 20 Days | Ultimate Khumbu | Yeti Routes','20-day Everest Three Passes Trek: Kongma La, Cho La & Renjo La. EBC, Kala Patthar, Gokyo Lakes. The ultimate Khumbu circuit. Yeti Routes Nepal.',1),(22,3,NULL,NULL,'Gokyo Lakes & Gokyo Ri Trek','gokyo-lakes-trek','moderate',12,5357,'March to May, October to November','mixed','trek',6,0,1150.00,'USD',NULL,'Turquoise lakes and the best panoramic views of Everest.','Itinerary: Lukla > Dole > Machhermo > Gokyo > Gokyo Ri > Return.','[\"Summit Gokyo Ri (5,357m) for panoramic views of four 8,000m peaks: Everest, Lhotse, Makalu, Cho Oyu\", \"Explore the sacred turquoise Gokyo Lakes — the world\'s highest freshwater lake system\", \"Walk across Ngozumpa Glacier, the largest glacier in Nepal\", \"Less crowded and more serene than the Everest Base Camp trail\", \"Spot migratory birds and Himalayan wildlife in the upper Gokyo Valley\", \"Optional extension via Cho La Pass (5,420m) to Everest Base Camp\"]','[\"Airport and hotel transfers in Kathmandu\", \"Lukla round-trip flight (Kathmandu–Lukla–Kathmandu)\", \"Tea house accommodation throughout the trek\", \"All meals on trek (breakfast, lunch, dinner)\", \"Experienced English-speaking trekking guide\", \"One porter per two trekkers (max 15 kg luggage)\", \"Sagarmatha National Park entry permit\", \"TIMS card\", \"First aid kit and pulse oximeter\", \"Yeti Routes duffel bag and trekking map\"]','[\"International flights to/from Nepal\", \"Nepal entry visa fee\", \"Travel and rescue insurance (mandatory)\", \"Meals and accommodation in Kathmandu\", \"Personal trekking gear\", \"Personal expenses (hot shower, charging, bottled water)\", \"Alcoholic beverages and soft drinks\", \"Tips for guides and porters\", \"Helicopter rescue costs if required\"]',NULL,NULL,0,NULL,NULL,NULL,'Gokyo Lakes & Gokyo Ri Trek | 12 Days | Yeti Routes','Trek to the sacred Gokyo Lakes and summit Gokyo Ri (5,357m) for views of four 8,000m peaks. 12 days, small groups, expert guides.',1),(23,3,NULL,NULL,'Ama Dablam Base Camp Trek','ama-dablam-base-camp','moderate',12,4600,'March to May, October to November','mixed','trek',6,0,1050.00,'USD',NULL,'Get up close to the most beautiful mountain in the Himalayas.','Itinerary: Lukla > Namche > Pangboche > Ama Dablam BC > Return.','[\"Approach the iconic Ama Dablam (6,812m) — widely regarded as the most beautiful mountain in the Himalayas\", \"Up-close views of the dramatic south-west face and hanging glacier of Ama Dablam\", \"Trek through Sagarmatha National Park, a UNESCO World Heritage Site\", \"Visit the ancient Tengboche Monastery set against a spectacular mountain backdrop\", \"Immersive Sherpa culture in Namche Bazaar and surrounding villages\", \"Rarely crowded trail — a hidden gem of the Khumbu region\"]','[\"Airport and hotel transfers in Kathmandu\", \"Lukla round-trip flight (Kathmandu–Lukla–Kathmandu)\", \"Tea house accommodation throughout the trek\", \"All meals on trek (breakfast, lunch, dinner)\", \"Experienced English-speaking trekking guide\", \"One porter per two trekkers (max 15 kg luggage)\", \"Sagarmatha National Park entry permit\", \"TIMS card\", \"First aid kit and pulse oximeter\", \"Yeti Routes duffel bag and trekking map\"]','[\"International flights to/from Nepal\", \"Nepal entry visa fee\", \"Travel and rescue insurance (mandatory)\", \"Meals and accommodation in Kathmandu\", \"Personal trekking gear\", \"Personal expenses (hot shower, charging, bottled water)\", \"Alcoholic beverages and soft drinks\", \"Tips for guides and porters\", \"Helicopter rescue costs if required\"]',NULL,NULL,0,NULL,NULL,NULL,'Ama Dablam Base Camp Trek | 12 Days | Yeti Routes','Trek to the base of Ama Dablam (6,812m), the most beautiful peak in the Himalayas. 12 days, less crowded, expert guides. Yeti Routes Nepal.',1),(24,3,NULL,NULL,'Everest View Trek','everest-view-trek','easy',7,3860,'March to May, October to November','forest','tour',4,0,850.00,'USD',NULL,'A short, easy trek to experience Sherpa culture and Everest views.','Itinerary: Lukla > Phakding > Namche > Tengboche > Return.','[\"See Mt. Everest with your own eyes from the famous Everest View Hotel (3,880m) — highest hotel in the world\", \"Trek into the heart of Sherpa country without the physical demands of EBC\", \"Explore vibrant Namche Bazaar — the Everest region\'s bustling hub\", \"Visit Khumjung village and see the legendary Yeti scalp at the monastery\", \"Short scenic Lukla mountain flight, one of the world\'s most thrilling runways\", \"Ideal for trekkers who want authentic Himalayan experience without extreme altitude\"]','[\"Airport and hotel transfers in Kathmandu\", \"Lukla round-trip flight (Kathmandu–Lukla–Kathmandu)\", \"Tea house accommodation throughout the trek\", \"All meals on trek (breakfast, lunch, dinner)\", \"Experienced English-speaking trekking guide\", \"One porter per two trekkers (max 15 kg luggage)\", \"Sagarmatha National Park entry permit\", \"TIMS card\", \"First aid kit\", \"Yeti Routes duffel bag and trekking map\"]','[\"International flights to/from Nepal\", \"Nepal entry visa fee\", \"Travel and rescue insurance (mandatory)\", \"Meals and accommodation in Kathmandu\", \"Personal trekking gear\", \"Personal expenses\", \"Alcoholic beverages and soft drinks\", \"Tips for guides and porters\"]',NULL,NULL,0,NULL,NULL,NULL,'Everest View Trek | 7 Days | Easy | From $850 | Yeti Routes','7-day Everest View Trek — see Mt. Everest from Namche Bazaar. Easy altitude, Sherpa culture, Lukla mountain flight. Perfect for beginners. Yeti Routes.',1),(25,10,NULL,NULL,'Annapurna Base Camp Trek','annapurna-base-camp','moderate',10,4130,'March to May, October to November','mixed','trek',6,0,890.00,'USD',NULL,'Journey into the heart of the Annapurna Sanctuary.','Itinerary: Nayapul > Ghandruk > Chhomrong > Deurali > ABC > Bamboo > Jhinu > Pokhara.','[\"Reach Annapurna Base Camp (4,130m), encircled by a 360° amphitheatre of Himalayan giants\", \"Wake up to sunrise turning Annapurna South, Machhapuchhre, and Hiunchuli golden\", \"Trek through dense rhododendron forests ablaze with colour in spring\", \"Soak in the natural hot springs at Jhinu Danda after the trek\", \"Walk through traditional Gurung and Magar villages with rich cultural heritage\", \"Close-up views of the sacred Machhapuchhre (Fishtail) peak — never climbed\"]','[\"Airport and hotel transfers in Kathmandu\", \"Kathmandu–Pokhara–Kathmandu transport\", \"Tea house accommodation throughout the trek\", \"All meals on trek (breakfast, lunch, dinner)\", \"Experienced English-speaking trekking guide\", \"One porter per two trekkers (max 15 kg luggage)\", \"Annapurna Conservation Area permit (ACAP)\", \"TIMS card\", \"First aid kit and pulse oximeter\", \"Yeti Routes duffel bag and trekking map\"]','[\"International flights to/from Nepal\", \"Nepal entry visa fee\", \"Travel and rescue insurance (mandatory)\", \"Meals and accommodation in Kathmandu and Pokhara\", \"Personal trekking gear\", \"Personal expenses (hot shower, charging, bottled water)\", \"Alcoholic beverages and soft drinks\", \"Tips for guides and porters\", \"Helicopter rescue costs if required\"]',NULL,NULL,1,NULL,NULL,NULL,'Annapurna Base Camp Trek | 10 Days | From $890 | Yeti Routes','10-day Annapurna Base Camp Trek (4,130m). 360° Himalayan views, rhododendron forests & hot springs. Expert guides. Book with Yeti Routes Nepal.',1),(26,10,NULL,NULL,'Annapurna Circuit Trek','annapurna-circuit','challenging',16,5416,'March to May, October to November','mixed','expedition',7,0,1050.00,'USD',NULL,'The classic circle around the Annapurna Massif.','Itinerary: Besisahar > Pisang > Manang > Yak Kharka > Thorang La > Muktinath > Jomsom > Tatopani.','[\"Cross the iconic Thorong La Pass (5,416m) — one of the world\'s highest trekking passes\", \"Visit the sacred Hindu and Buddhist temples of Muktinath (3,760m)\", \"Explore Tilicho Lake (4,919m) — one of the world\'s highest lakes (optional extension)\", \"Experience the dramatic kali Gandaki Gorge, the world\'s deepest gorge\", \"Poon Hill sunrise (3,210m) with panoramic views of Dhaulagiri and Annapurna ranges\", \"Complete circuit of the entire Annapurna massif through diverse landscapes\"]','[\"Airport and hotel transfers in Kathmandu\", \"Kathmandu–Besisahar and Pokhara–Kathmandu transport\", \"Tea house accommodation throughout the trek\", \"All meals on trek (breakfast, lunch, dinner)\", \"Experienced English-speaking trekking guide\", \"One porter per two trekkers (max 15 kg luggage)\", \"Annapurna Conservation Area permit (ACAP)\", \"TIMS card\", \"First aid kit and pulse oximeter\", \"Sleeping bag (rental available for high sections)\", \"Yeti Routes duffel bag and trekking map\"]','[\"International flights to/from Nepal\", \"Nepal entry visa fee\", \"Travel and rescue insurance (mandatory)\", \"Meals and accommodation in Kathmandu and Pokhara\", \"Personal trekking gear\", \"Personal expenses\", \"Alcoholic beverages and soft drinks\", \"Tips for guides and porters\", \"Helicopter rescue costs if required\"]',NULL,NULL,0,NULL,NULL,NULL,'Annapurna Circuit Trek | 16 Days | Thorong La | Yeti Routes','16-day Annapurna Circuit Trek. Thorong La Pass (5,416m), Muktinath, Poon Hill & Kali Gandaki Gorge. The classic Nepal circuit. Yeti Routes.',0),(27,10,NULL,NULL,'North Annapurna Base Camp','north-annapurna-base-camp','challenging',9,4190,'March to May, October to November','mixed','trek',7,0,1200.00,'USD',NULL,'The trail of Maurice Herzog. Less crowded, wilder alternative.','Itinerary: Sekong Lake > Narchyang > Humkhola > North ABC > Return.','[\"Reach the rarely visited North Annapurna Base Camp with stunning views of Annapurna II and IV\", \"Off-the-beaten-path trail through the classic Annapurna Circuit\'s upper valleys\", \"Dramatic high-altitude terrain near the Nepal-Tibet border\", \"Acclimatize in historic Manang village, gateway to the high Himalayas\", \"Views of Tilicho Lake basin and the barren plateau landscape near Thorong La\", \"Authentic Manangi cultural experience with minimal tourist infrastructure\"]','[\"Airport and hotel transfers in Kathmandu\", \"Kathmandu–Besisahar–Kathmandu transport\", \"Tea house accommodation throughout the trek\", \"All meals on trek (breakfast, lunch, dinner)\", \"Experienced English-speaking trekking guide\", \"One porter per two trekkers (max 15 kg luggage)\", \"Annapurna Conservation Area permit (ACAP)\", \"TIMS card\", \"First aid kit and pulse oximeter\", \"Yeti Routes duffel bag and trekking map\"]','[\"International flights to/from Nepal\", \"Nepal entry visa fee\", \"Travel and rescue insurance (mandatory)\", \"Meals and accommodation in Kathmandu\", \"Personal trekking gear\", \"Personal expenses\", \"Alcoholic beverages and soft drinks\", \"Tips for guides and porters\", \"Helicopter rescue costs if required\"]',NULL,NULL,0,NULL,NULL,NULL,'North Annapurna Base Camp Trek | 9 Days | Yeti Routes','Off-the-beaten-path 9-day trek to North Annapurna Base Camp. Dramatic Himalayan terrain, Manang valley, Annapurna II and IV views. Yeti Routes Nepal.',1),(28,10,NULL,NULL,'Mardi Himal Trek','mardi-himal-trek','moderate',7,4500,'March to May, October to November','forest','tour',5,0,650.00,'USD',NULL,'Short, scenic ridge trek with close-up views of Machhapuchhre.','Itinerary: Kande > Forest Camp > High Camp > Mardi BC > Siding.','[\"Climb to Mardi Himal High Camp (4,500m) with up-close views of Machhapuchhre and Annapurna South\", \"Walk a pristine, less-crowded alternative trail in the heart of the Annapurna region\", \"Diverse forest landscape from rhododendron to bamboo to high alpine meadows\", \"Classic views of the Annapurna range from a completely different perspective\", \"Authentic mountain experience with traditional teahouse culture\", \"Annapurna Conservation Area — rich bird life and Himalayan flora\"]','[\"Airport and hotel transfers in Kathmandu\", \"Kathmandu–P